INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8924, 'តាមអ៊ីស្តូក្រាម ចំនួនគ្រួសារដែលប្រើអគ្គិសនីអស់យ៉ាងតិច ៣០ ម៉ឺនរៀល (៣០ ដល់ ៣៥ ម៉ឺនរៀល) គឺ ៖', 'g8-8afbba5f72.svg', '["២៥ គ្រួសារ", "១២ គ្រួសារ", "៥ គ្រួសារ", "៤០ គ្រួសារ"]', 2, NULL, 2, 'mcq', 'ចន្លោះ 30-35 មានប្រេកង់ស្មើ 5 គ្រួសារ។', 'ស្ថិតិ', 'medium', 1, '8', 'ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8925, 'ទិន្នន័យ ៥ តួមាន \(6, 8, 10, x, 14\) និងមានមធ្យមស្មើ \(10\)។ តម្លៃនៃ \(x\) គឺ ៖', NULL, '["\\(12\\)", "\\(15\\)", "\\(10\\)", "\\(8\\)"]', 0, NULL, 3, 'mcq', '\(\dfrac{38 + x}{5} = 10 \Rightarrow 38 + x = 50 \Rightarrow x = 12\)។', 'ស្ថិតិ', 'hard', 1, '8', 'ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8926, 'ចន្លោះថ្នាក់ \(10 - 20\) (ប្រេកង់ 4) និង \(20 - 30\) (ប្រេកង់ 6)។ មធ្យមប្រមាណនៃទិន្នន័យទាំង ១០ គឺ ៖', NULL, '["\\(25\\)", "\\(21\\)", "\\(22\\)", "\\(20\\)"]', 1, NULL, 3, 'mcq', 'តម្លៃកណ្តាល 15 និង 25 ៖ \(\bar{x} = \dfrac{4(15) + 6(25)}{10} = \dfrac{60 + 150}{10} = 21\)។', 'ស្ថិតិ', 'hard', 1, '8', 'ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8927, 'ទិន្នន័យ ៤ ចំនួនគត់វិជ្ជមានមានម៉ូតស្មើ 5 មេដ្យានស្មើ 6 និងមធ្យមស្មើ 7។ តម្លៃធំជាងគេគឺ ៖', NULL, '["\\(10\\)", "\\(11\\)", "\\(12\\)", "\\(14\\)"]', 2, NULL, 3, 'mcq', 'ដោយម៉ូត 5 នាំឱ្យមានលេខ 5 ពីរដង (5, 5, a, b)។ មេដ្យាន 6 នាំឱ្យ \((5+a)/2 = 6 \Rightarrow a = 7\)។ ផលបូក \(4 \times 7 = 28 \Rightarrow 5+5+7+b = 28 \Rightarrow b = 12\)។', 'ស្ថិតិ', 'hard', 1, '8', 'ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8928, 'ត្រួតពិនិត្យផ្លែប៉ោម ១០០ កេសពីប្រទេស A (ស្អុយសរុប 358 ផ្លែ) និង ១០០ កេសពីប្រទេស B (ស្អុយសរុប 99 ផ្លែ)។ មធ្យមផ្លែប៉ោមស្អុយក្នុងមួយកេសនៃប្រទេស B គឺ ៖', NULL, '["\\(0.5\\ \\text{ផ្លែ/កេស}\\)", "\\(3.58\\ \\text{ផ្លែ/កេស}\\)", "\\(1.5\\ \\text{ផ្លែ/កេស}\\)", "\\(0.99\\ \\text{ផ្លែ/កេស}\\)"]', 3, NULL, 3, 'mcq', '\(\bar{x}_B = \dfrac{99}{100} = 0.99\) ផ្លែក្នុងមួយកេស។', 'ស្ថិតិ', 'hard', 1, '8', 'ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8929, 'ទិន្នន័យ ៦ តួមានមធ្យមស្មើ 15។ បើគេបន្ថែមទិន្នន័យមួយទៀតគឺ 22 នោះមធ្យមថ្មីនៃទិន្នន័យទាំង ៧ គឺ ៖', NULL, '["\\(15.5\\)", "\\(16\\)", "\\(17\\)", "\\(18.5\\)"]', 1, NULL, 3, 'mcq', 'ផលបូកចាស់ \(6 \times 15 = 90\) ; ផលបូកថ្មី \(90 + 22 = 112 \Rightarrow \bar{x} = \dfrac{112}{7} = 16\)។', 'ស្ថិតិ', 'hard', 1, '8', 'ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8930, 'ផ្អែកលើទិន្នន័យផ្លែប៉ោមខាងលើ ការនាំចូលពីប្រទេសណាមានគុណភាពល្អជាង (ខូចខាតតិចជាង)?', NULL, '["មិនអាចប្រៀបធៀបបាន", "ប្រទេសទាំងពីរស្មើគ្នា", "ប្រទេស A ល្អជាង", "ប្រទេស B ល្អជាង (ស្អុយមធ្យម 0.99 ផ្លែ/កេស)"]', 3, NULL, 3, 'mcq', 'ប្រទេស B មានផ្លែប៉ោមស្អុយសរុបតែ 99 ផ្លែ តិចជាងប្រទេស A ឆ្ងាយណាស់ (358 ផ្លែ)។', 'ស្ថិតិ', 'hard', 1, '8', 'ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8931, 'ក្នុងថ្នាក់មួយ សិស្សប្រុស ១០ នាក់មានពិន្ទុមធ្យម ៧ និងសិស្សស្រី ២០ នាក់មានពិន្ទុមធ្យម ៨.៥។ ពិន្ទុមធ្យមនៃសិស្សទាំង ៣០ នាក់គឺ ៖', NULL, '["\\(7.75\\)", "\\(8.25\\)", "\\(8\\)", "\\(7.5\\)"]', 2, NULL, 3, 'mcq', '\(\bar{x} = \dfrac{10(7) + 20(8.5)}{30} = \dfrac{70 + 170}{30} = \dfrac{240}{30} = 8\)។', 'ស្ថិតិ', 'hard', 1, '8', 'ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8932, 'គ្រូបង្រៀន ២៦ នាក់បានកត់ត្រាម៉ោងកែកិច្ចការសិស្ស ៖ ១h: 5នាក់, ២h: 8នាក់, ៣h: 6នាក់, ៤h: 4នាក់, ៥h: 2នាក់, ៦h: 1នាក់។ ម៉ោងរួមដែលគ្រូភាគច្រើនបានចំណាយ (ម៉ូត) គឺ ៖', NULL, '["\\(2\\ \\text{ម៉ោង}\\)", "\\(6\\ \\text{ម៉ោង}\\)", "\\(3\\ \\text{ម៉ោង}\\)", "\\(1\\ \\text{ម៉ោង}\\)"]', 0, NULL, 3, 'mcq', 'ប្រេកង់ខ្ពស់ជាងគេគឺ 8 នាក់ ដែលត្រូវនឹង 2 ម៉ោង នាំឱ្យម៉ូតគឺ 2 ម៉ោង។', 'ស្ថិតិ', 'pisa', 1, '8', 'ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8933, 'តារាងប្រាក់ចំណូលសប្តាហ៍របស់អាជីវករ ៦៨ នាក់បង្ហាញថា ចំនួនអាជីវករដែលរកប្រាក់បានតិចជាង ១០០ ម៉ឺនរៀលមានចំនួន ៖', NULL, '["\\(20\\ \\text{នាក់}\\)", "\\(40\\ \\text{នាក់}\\)", "\\(48\\ \\text{នាក់}\\)", "\\(34\\ \\text{នាក់}\\)"]', 3, NULL, 3, 'mcq', '\(4 + 6 + 8 + 16 = 34\) នាក់ (ស្មើនឹង 50% នៃអាជីវករសរុប)។', 'ស្ថិតិ', 'pisa', 1, '8', 'ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8934, 'តាមការស្ទង់មតិលើអតិថិជនប្រើអគ្គិសនី ចំនួនគ្រួសារដែលចំណាយអស់តិចជាង ២០ ម៉ឺនរៀល (ចន្លោះ 10-15 និង 15-20) គឺ ៖', NULL, '["\\(40\\ \\text{គ្រួសារ}\\)", "\\(32\\ \\text{គ្រួសារ}\\)", "\\(97\\ \\text{គ្រួសារ}\\)", "\\(72\\ \\text{គ្រួសារ}\\)"]', 3, NULL, 3, 'mcq', '\(32 + 40 = 72\) គ្រួសារ។', 'ស្ថិតិ', 'pisa', 1, '8', 'ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8935, 'ក្នុងចំណោមគ្រូបង្រៀន ៥០ នាក់ មាន ៣០ នាក់មានអាយុតិចជាង ៥០ ឆ្នាំ។ ភាគរយនៃគ្រូដែលមានអាយុចាប់ពី ៥០ ឆ្នាំឡើងទៅគឺ ៖', NULL, '["\\(30\\%\\)", "\\(40\\%\\)", "\\(50\\%\\)", "\\(60\\%\\)"]', 1, NULL, 3, 'mcq', 'គ្រូអាយុចាប់ពី 50 ឆ្នាំមាន \(50 - 30 = 20\) នាក់ នាំឱ្យភាគរយគឺ \(\dfrac{20}{50} \times 100\% = 40\%\)។', 'ស្ថិតិ', 'pisa', 1, '8', 'ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8936, 'បេក្ខជន ២៨ នាក់ប្រឡងភាសាអង់គ្លេស។ បើពិន្ទុជាប់គឺចាប់ពី ៦០ ពិន្ទុឡើងទៅ ហើយមានបេក្ខជន ២១ នាក់បានពិន្ទុចាប់ពី ៦០ ឡើង អត្រាជាប់គឺ ៖', NULL, '["\\(80\\%\\)", "\\(70\\%\\)", "\\(65\\%\\)", "\\(75\\%\\)"]', 3, NULL, 3, 'mcq', '\(\dfrac{21}{28} \times 100\% = \dfrac{3}{4} \times 100\% = 75\%\)។', 'ស្ថិតិ', 'pisa', 1, '8', 'ស្ថិតិ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8937, 'គេឱ្យទិន្នន័យ ៖ \(3, 7, 5, 9, 7, 6, 7, 8, 2\)។ ក. តម្រៀបទិន្នន័យតាមលំដាប់កើន។ ខ. រកម៉ូត។ គ. រកមេដ្យាន។ ឃ. គណនាមធ្យម។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. តម្រៀបតាមលំដាប់កើន ៖ \(2, 3, 5, 6, 7, 7, 7, 8, 9\) (1 ពិន្ទុ)
