INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8939, 'គេស្ទង់មតិគ្រូបង្រៀន ២៦ នាក់ពីម៉ោងកែកិច្ចការសិស្ស ៖ 1h (5នាក់), 2h (8នាក់), 3h (6នាក់), 4h (4នាក់), 5h (2នាក់), 6h (1នាក់)។ ក. រកចំនួនម៉ោងរួមដែលគ្រូភាគច្រើនបានចំណាយ។ ខ. គណនាម៉ោងមធ្យមដែលគ្រូម្នាក់ៗចំណាយ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ប្រេកង់ខ្ពស់ជាងគេគឺ 8 នាក់ ត្រូវនឹង \(2\ \text{ម៉ោង}\) នាំឱ្យម៉ូត \(M_o = 2\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8940, 'ទិន្នន័យកម្ពស់សិស្ស ៦ នាក់គិតជា cm គឺ ៖ \(148, 152, 150, 156, 154, 150\)។ ក. រកកម្ពស់មធ្យម។ ខ. រកមេដ្យាន។ គ. រកម៉ូត។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផលបូក ៖ \(148 + 152 + 150 + 156 + 154 + 150 = 910\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8941, 'តារាងប្រេកង់នៃពិន្ទុសិស្ស ២០ នាក់ ៖ ពិន្ទុ 5 (3នាក់), ពិន្ទុ 6 (5នាក់), ពិន្ទុ 7 (7នាក់), ពិន្ទុ 8 (4នាក់), ពិន្ទុ 9 (1នាក់)។ ក. រកម៉ូត។ ខ. រកមេដ្យាន។ គ. គណនាពិន្ទុមធ្យម។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ម៉ូត \(M_o = 7\) (ប្រេកង់ខ្ពស់ជាងគេគឺ 7 នាក់) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8942, 'ទិន្នន័យ ៦ ចំនួនមាន \(4, 7, 9, x, 12, 15\)។ ក. រក \(x\) បើមធ្យមស្មើ 10។ ខ. ជាមួយតម្លៃ \(x\) នោះ ចូរកំណត់មេដ្យាន។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផលបូក ៖ \(4 + 7 + 9 + x + 12 + 15 = 47 + x\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8943, 'តារាងចំណាយភ្លើងអគ្គិសនី (ម៉ឺនរៀល) ៖ 10-15 (32គ្រួសារ), 15-20 (40គ្រួសារ), 20-25 (25គ្រួសារ), 25-30 (12គ្រួសារ), 30-35 (5គ្រួសារ)។ ក. រកចំនួនគ្រួសារសរុប។ ខ. រកចំនួនគ្រួសារដែលចំណាយយ៉ាងតិច 25 ម៉ឺនរៀល។ គ. គណនាភាគរយនៃគ្រួសារដែលចំណាយក្រោម 20 ម៉ឺនរៀល។', 'g8-8afbba5f72.svg', '[]', 0, NULL, 5, 'writing', 'ក. ចំនួនគ្រួសារសរុប ៖ \(N = 32 + 40 + 25 + 12 + 5 = 114\ \text{គ្រួសារ}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8944, 'ក្នុងថ្នាក់មួយ សិស្សប្រុស ១២ នាក់មានពិន្ទុមធ្យម ៦.៥ និងសិស្សស្រី ១៨ នាក់មានពិន្ទុមធ្យម ៨.០។ ក. គណនាផលបូកពិន្ទុសិស្សប្រុស។ ខ. គណនាផលបូកពិន្ទុសិស្សស្រី។ គ. គណនាពិន្ទុមធ្យមនៃសិស្សទាំងអស់ក្នុងថ្នាក់។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផលបូកពិន្ទុប្រុស ៖ \(12 \times 6.5 = 78\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8945, 'តារាងប្រាក់ចំណូលសប្តាហ៍របស់អាជីវករ (ម៉ឺនរៀល) ៖ 80-85 (4នាក់), 85-90 (6នាក់), 90-95 (8នាក់), 95-100 (16នាក់), 100-105 (20នាក់), 105-110 (6នាក់), 110-115 (8នាក់)។ ក. រកចំនួនអាជីវករសរុប។ ខ. រកចំនួនអាជីវករដែលរកបានចាប់ពី 100 ម៉ឺនរៀលឡើងទៅ។ គ. រកថ្នាក់ដែលមានប្រេកង់ខ្ពស់ជាងគេ (ថ្នាក់ម៉ូត)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ចំនួនអាជីវករសរុប ៖ \(N = 4 + 6 + 8 + 16 + 20 + 6 + 8 = 68\ \text{នាក់}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8946, 'គេត្រួតពិនិត្យផ្លែប៉ោម ១០០ កេសពីប្រទេស A (ស្អុយសរុប 358 ផ្លែ) និង ១០០ កេសពីប្រទេស B (ស្អុយសរុប 99 ផ្លែ)។ ក. គណនាចំនួនផ្លែប៉ោមស្អុយជាមធ្យមក្នុងមួយកេសសម្រាប់ប្រទេសនីមួយៗ។ ខ. ធ្វើការប្រៀបធៀបគុណភាពផ្លែប៉ោមរវាងប្រទេសទាំងពីរ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មធ្យមប្រទេស A ៖ \(\bar{x}_A = \dfrac{358}{100} = 3.58\ \text{ផ្លែ/កេស}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8947, 'ស្ទង់មតិលើគ្រួសារ ១១៤ គ្រួសារអំពីចំណាយភ្លើងអគ្គិសនីប្រចាំខែ (ម៉ឺនរៀល) ៖ 10-15 (32), 15-20 (40), 20-25 (25), 25-30 (12), 30-35 (5)។ ក. រកថ្នាក់ដែលមានចំនួនគ្រួសារច្រើនជាងគេ។ ខ. រកចំនួនគ្រួសារដែលចំណាយចាប់ពី ២៥ ម៉ឺនរៀលឡើងទៅ។ គ. គណនាភាគរយនៃគ្រួសារដែលចំណាយចាប់ពី ២៥ ម៉ឺនរៀលឡើង។', 'g8-8afbba5f72.svg', '[]', 0, NULL, 5, 'writing', 'ក. ថ្នាក់ចំណាយច្រើនជាងគេគឺ 15-20 ម៉ឺនរៀល (មាន 40 គ្រួសារ) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8948, 'តារាងប្រាក់ចំណូលសប្តាហ៍របស់អាជីវករ ៦៨ នាក់ ៖ រកបានក្រោម ១០០ ម៉ឺនរៀលមាន ៣៤ នាក់ និងរកបានចាប់ពី ១០០ ម៉ឺនរៀលឡើងទៅមាន ៣៤ នាក់។ ក. គណនាភាគរយនៃអាជីវករដែលរកបានក្រោម ១០០ ម៉ឺនរៀល។ ខ. តើមេដ្យាននៃប្រាក់ចំណូលស្ថិតនៅចន្លោះថ្នាក់ណា? គ. ផ្តល់យោបល់ដើម្បីបង្កើនចំណូលអាជីវករ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ភាគរយ ៖ \(\dfrac{34}{68} \times 100\% = 50\%\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8949, 'គ្រូបង្រៀន ៥០ នាក់ត្រូវបានស្ទង់មតិពីអាយុ។ មាន ៦ នាក់អាយុ 30-35, ៥ នាក់អាយុ 35-40, ៦ នាក់អាយុ 40-45, ១៣ នាក់អាយុ 45-50, ៩ នាក់អាយុ 50-55, ៧ នាក់អាយុ 55-60, ៤ នាក់អាយុ 60-65។ ក. រកចំនួនគ្រូអាយុតិចជាង ៥០ ឆ្នាំ។ ខ. រកភាគរយនៃគ្រូអាយុតិចជាង ៥០ ឆ្នាំ។ គ. រកថ្នាក់អាយុដែលមានគ្រូច្រើនជាងគេ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. គ្រូអាយុតិចជាង 50 ឆ្នាំ ៖ \(6 + 5 + 6 + 13 = 30\ \text{នាក់}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8950, 'លទ្ធផលតេស្តភាសាអង់គ្លេសបេក្ខជន ២៨ នាក់ ៖ ពិន្ទុចាប់ពី 60 ឡើងមាន 21 នាក់ និងក្រោម 60 មាន 7 នាក់។ ក. គណនាអត្រាជាប់ (ចាប់ពី 60 ពិន្ទុ)។ ខ. គណនាអត្រាធ្លាក់។ គ. បើចង់ឱ្យអត្រាជាប់កើនដល់ 85% តើត្រូវការបេក្ខជនជាប់ប៉ុន្មាននាក់យ៉ាងតិច?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. អត្រាជាប់ ៖ \(\dfrac{21}{28} \times 100\% = 75\%\) (2 ពិន្ទុ)
